import os
for k in ['OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS']:os.environ[k]='1'
from pathlib import Path
import json,time,shutil
import pandas as pd,numpy as np
import baseline as b
R=Path(__file__).resolve().parents[1];A=R.parent;INPUT=A/'ranking-pipeline-20261020/input';RAW=A/'exploration-12h-20261017/raw'
COVER=['risk_conditional_negative_months','risk_conditional_nonnegative_months','aux_account_months','aux_orders90','aux_ecommerce_observed_days','aux_allocation_count']
def main():
 assert not(R/'PREPARED.json').exists();plan=json.loads((R/'plan.json').read_text());assert plan['user_requested_full_data_refit']and time.time()<plan['refit_deadline']
 selected=A/'shopping-periodicity-fe-20261021';assert json.loads((selected/'FINAL_STATUS.json').read_text())['status']=='passed';assert b.sha(selected/'true_features.parquet')==json.loads((selected/'BUILD_COMPLETE.json').read_text())['feature_hashes']['true']
 frame=pd.read_parquet(INPUT/'data/train_features.parquet',columns=['application_id','customer_id','target']);assert len(frame)==70000 and frame.target.isin([0,1]).all();apps=pd.concat([pd.read_csv(RAW/(s+'_applications.csv'),usecols=['application_id','customer_id','decision_datetime'],parse_dates=['decision_datetime'])for s in ['train','test']],ignore_index=True);assert len(apps)==100000 and apps.customer_id.is_unique and apps.application_id.is_unique
 assert apps.application_id.iloc[:70000].tolist()==frame.application_id.tolist();assert apps.customer_id.iloc[:70000].tolist()==frame.customer_id.tolist();apps['row']=np.arange(len(apps));apps.to_parquet(R/'applications.parquet',index=False);sample=pd.read_csv(RAW/'sample_submission(3).csv');assert len(sample)==30000 and set(sample.application_id)==set(apps.application_id.iloc[70000:]);sample.to_csv(R/'sample_submission.csv',index=False)
 dest=R/'input';(dest/'data').mkdir(parents=True);(dest/'data/train_features.parquet').symlink_to(INPUT/'data/train_features.parquet');shutil.copy2(INPUT/'BASELINE_LOCK.json',dest/'BASELINE_LOCK.json');idx_hashes={}
 for f in range(5):
  old=np.load(INPUT/f'artifacts/fold{f}/indices.npz');head=old['correction'];context=np.setdiff1d(np.arange(70000),head);assert len(context)==64000 and len(head)==6000 and not np.intersect1d(context,head).size;assert np.array_equal(np.sort(np.r_[context,head]),np.arange(70000));out=dest/f'artifacts/fold{f}';out.mkdir(parents=True);np.savez_compressed(out/'indices.npz',context=context,correction=head,train=np.arange(70000),validation=np.array([],dtype=int));idx_hashes[str(f)]=b.sha(out/'indices.npz')
 lookup=apps[['customer_id','row','decision_datetime']];out=apps[['application_id']].copy();n=len(apps)
 def history(name,dates):return pd.read_csv(RAW/(name+'.csv'),parse_dates=dates).merge(lookup,on='customer_id',validate='many_to_one')
 def counts(s,fill=0):return s.reindex(np.arange(n),fill_value=fill).to_numpy()
 ac=history('account_behavior',['month']);assert not ac.duplicated(['row','month']).any();ac=ac[(ac.month+pd.offsets.MonthBegin(1))<=ac.decision_datetime].copy();ac['net']=ac.inflows-ac.outflows;recent=ac.month>=ac.decision_datetime.dt.to_period('M').dt.to_timestamp()-pd.DateOffset(months=3);out['aux_account_months']=counts(ac[recent].groupby('row').size())
 rep=history('repayment_history',['due_date','last_payment_datetime']);assert(rep.last_payment_datetime.isna()|(rep.last_payment_datetime<rep.decision_datetime)).all();rep=rep[rep.due_date<rep.decision_datetime].copy();out['aux_allocation_count']=counts(rep[rep.last_payment_datetime.notna()].groupby('row').size());age=(rep.decision_datetime.dt.normalize()-rep.due_date.dt.normalize()).dt.days;part=rep[age>=15].copy();part['month']=part.due_date.dt.to_period('M').dt.to_timestamp();part['allocated']=part.last_payment_datetime.notna();month=part.groupby(['row','month']).allocated.sum().reset_index().merge(ac[['row','month','net']],on=['row','month'],validate='one_to_one');out['risk_conditional_negative_months']=counts(month[(month.allocated>0)&(month.net<0)].groupby('row').size());out['risk_conditional_nonnegative_months']=counts(month[(month.allocated>0)&(month.net>=0)].groupby('row').size())
 ec=history('ecommerce_transactions',['transaction_datetime']);assert(ec.transaction_datetime<ec.decision_datetime).all();assert ec.groupby('order_id').order_total.nunique().max()==1;orders=ec.drop_duplicates('order_id').copy();orders['age']=(orders.decision_datetime-orders.transaction_datetime).dt.total_seconds()/86400;out['aux_orders90']=counts(orders[orders.order_status.eq('completed')&orders.age.between(0,90,inclusive='right')].groupby('row').size());out['aux_ecommerce_observed_days']=counts(orders.groupby('row').age.max(),np.nan)
 ref=pd.read_parquet(A/'coverage-transfer-20261021/data/features.parquet').set_index('application_id').loc[frame.application_id];assert all(np.array_equal(out[c].iloc[:70000].to_numpy(),ref[c].to_numpy(),equal_nan=True)for c in COVER)
 external=pd.read_parquet(A/'coverage-transfer-20261021/evidence/extension/data/raw_features.parquet',columns=['application_id','ext_aux_allocation_negative_n','ext_aux_allocation_nonnegative_n']).set_index('application_id').loc[apps.application_id]
 for name in ['negative','nonnegative']:assert np.array_equal(out['risk_conditional_'+name+'_months'].to_numpy(),external['ext_aux_allocation_'+name+'_n'].to_numpy())
 out.to_parquet(R/'coverage.parquet',index=False)
 feature_plan=json.loads((A/'fold-local-priors-20261021/plan.json').read_text());feature_plan.update(id=R.name+'-features',input=str(dest),refit_deadline=plan['refit_deadline'],full_data_refit=True);b.dump(feature_plan,R/'feature_build/plan.json');b.dump(dict(status='passed',train_rows=70000,test_rows=30000,coverage_train_exact=True,conditional_counts100k_exact=True,context_rows=64000,correction_rows=6000,spline_rows=70000,all_training_labels_used_per_run=True,training_test_customers_disjoint=True,index_hashes=idx_hashes,sample_sha256=b.sha(R/'sample_submission.csv'),coverage_sha256=b.sha(R/'coverage.parquet'),applications_sha256=b.sha(R/'applications.parquet'),selected_feature_sha256=b.sha(selected/'true_features.parquet')),R/'PREPARED.json');print('Prepared full70000labelrefit; coverage paritypassed.',flush=True)
if __name__=='__main__':main()
